.sl-hero-search {
  background-color: var(--smartlearn-bg);
  color: var(--smartlearn-text);
  font-family: var(--smartlearn-body-font, system-ui, -apple-system, sans-serif);
  min-height: 75vh;
  display: flex;
  align-items: center;
  position: relative;
  padding-block: clamp(3rem, 6vw, 5.5rem);
}
.sl-hero-search::before {
  content: '';
  position: absolute;
  inset: 0;
  background: radial-gradient(circle at 50% 0%, color-mix(in srgb, var(--smartlearn-primary) 8%, transparent) 0%, transparent 70%);
  pointer-events: none;
}
.sl-hero-search .sl-text-primary { color: var(--smartlearn-primary); }
.sl-hero-search .sl-text-emphasis {
  color: var(--smartlearn-text);
  font-family: var(--smartlearn-heading-font, var(--smartlearn-body-font, system-ui, -apple-system, sans-serif));
}
.sl-hero-search .sl-text-muted { color: var(--smartlearn-text-muted); }
.sl-hero-search .sl-bg-card {
  background-color: var(--smartlearn-card-bg);
  border: 1px solid var(--smartlearn-card-border);
}
.sl-hero-search .sl-btn-primary {
  background-color: var(--smartlearn-btn-bg);
  border: 1px solid var(--smartlearn-btn-bg);
  color: var(--smartlearn-btn-text, #ffffff);
}
.sl-hero-search .sl-btn-primary:hover,
.sl-hero-search .sl-btn-primary:focus-visible {
  background-color: var(--smartlearn-btn-hover-bg, var(--smartlearn-primary-hover));
  border-color: var(--smartlearn-btn-hover-bg, var(--smartlearn-primary-hover));
  color: var(--smartlearn-btn-text, #ffffff);
}
.sl-hero-search .sl-subtitle {
  max-width: 600px;
}
.sl-hero-search .sl-search-title {
  letter-spacing: -0.02em;
}
.sl-hero-search .search-container {
  max-width: 800px;
}
.sl-hero-search .search-box {
  background-color: var(--smartlearn-input-bg);
  border: 1px solid var(--smartlearn-input-border, var(--smartlearn-card-border));
  box-shadow: 0 10px 25px rgba(0, 0, 0, 0.06);
  transition: box-shadow 0.25s ease, transform 0.25s ease;
}
.sl-hero-search .search-box:focus-within {
  border-color: var(--smartlearn-primary);
  box-shadow: 0 0 0 3px color-mix(in srgb, var(--smartlearn-primary) 22%, transparent), 0 12px 28px rgba(0, 0, 0, 0.08);
}
.sl-hero-search .sl-search-input {
  color: var(--smartlearn-text);
  box-shadow: none;
}
.sl-hero-search .sl-search-input:focus-visible {
  outline: 2px solid var(--smartlearn-primary);
  outline-offset: 2px;
}
.sl-hero-search .sl-search-input::placeholder {
  color: var(--smartlearn-text-muted);
}
.sl-hero-search .search-dropdown {
  z-index: 10;
  visibility: hidden;
  opacity: 0;
  pointer-events: none;
  transform: translateY(8px);
  transition: opacity 0.2s ease, transform 0.2s ease, visibility 0.2s ease;
}
.sl-hero-search .search-container:focus-within .search-dropdown {
  visibility: visible;
  opacity: 1;
  pointer-events: auto;
  transform: translateY(0);
}
.sl-hero-search .dropdown-item:hover,
.sl-hero-search .dropdown-item:focus-visible {
  background-color: color-mix(in srgb, var(--smartlearn-primary) 12%, transparent);
  color: var(--smartlearn-primary);
}
.sl-hero-search .sl-tag {
  transition: transform 0.2s ease, border-color 0.2s ease, color 0.2s ease;
}
.sl-hero-search .sl-tag:hover,
.sl-hero-search .sl-tag:focus-visible {
  border-color: var(--smartlearn-primary);
  color: var(--smartlearn-primary);
}
.sl-hero-search .sl-tracking-wide {
  letter-spacing: 0.1em;
}
@media (prefers-reduced-motion: no-preference) {
  .sl-hero-search .search-box:focus-within,
  .sl-hero-search .sl-tag:hover {
    transform: translateY(-2px);
  }
}
@media (prefers-reduced-motion: reduce) {
  .sl-hero-search .search-box,
  .sl-hero-search .search-dropdown,
  .sl-hero-search .sl-tag {
    transition: none;
  }
}
